// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

library YieldPoolErrors {
  // ─── Shared ────────────────────────────────────────────────────────────────

  /// @dev amount argument must be greater than zero
  error ZeroAmount();

  /// @dev address argument must not be the zero address
  error ZeroAddress();

  /// @dev there is no accrued reward to claim
  error NoRewardToClaim();

  /// @dev caller is not the designated rewarder address
  error NotRewarder();

  /// @dev caller has no frozen rewards to claim
  error NoFrozenRewards();

  /// @dev batchClaim / batchUnstake was called with an empty array
  error EmptyStakeIds();

  /// @dev a batch function was called with an empty array
  error EmptyArray();

  /// @dev batchUnstake / batchCancelLpStake was called with more than the allowed number of ids
  error BatchTooLarge();

  /// @dev parallel arrays passed to a batch function must have the same length
  error ArrayLengthMismatch();

  // ─── ARC staking ───────────────────────────────────────────────────────────

  /// @dev the stake has already been unstaked or never existed
  error StakeNotActive();

  /// @dev caller is not the owner of the given stake
  error NotStakeOwner();

  /// @dev LP mode is active; new pure-ARC stakes are no longer accepted
  error ArcStakingDisabled();

  /// @dev the post-deploy window for batchStakeFor seeding has elapsed
  error StakeForWindowClosed();

  // ─── Mode switch ───────────────────────────────────────────────────────────

  /// @dev caller is not the lpActivator
  error NotLpActivator();

  /// @dev activateLpMode has already been called; it can only be called once
  error LpModeAlreadyActive();

  /// @dev the provided LP token address is invalid
  error InvalidLpToken();

  // ─── LP staking ────────────────────────────────────────────────────────────

  /// @dev LP mode is not yet active; addLiquidityAndStake / claimLpReward / cancelLpStake are disabled
  error LpModeNotActive();

  /// @dev the LP stake has already been cancelled or never existed
  error LpStakeNotActive();

  /// @dev caller is not the owner of the given LP stake
  error NotLpStakeOwner();

  /// @dev the LP stake has not yet satisfied the minimum staking duration for rewards
  error StakeNotYetEligible();
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

library YieldPoolEvents {
  // ─── ARC staking ───────────────────────────────────────────────────────────

  /// @dev emitted when a user opens a new ARC stake position
  event Staked(address indexed user, uint256 indexed stakeId, uint256 amount);

  /// @dev emitted when a user closes an ARC stake position (ARC returned)
  event Unstaked(address indexed user, uint256 indexed stakeId, uint256 amount);

  /// @dev emitted whenever USDT rewards are transferred to an ARC staker
  event Claimed(address indexed user, uint256 indexed stakeId, uint256 reward);

  /// @dev emitted when a USDT reward transfer fails on unstake (token paused / blacklisted);
  ///      the amount is tracked in frozenRewards and claimable once USDT is operational
  event RewardFrozen(
    address indexed user,
    uint256 indexed stakeId,
    uint256 amount
  );

  // ─── Mode switch ───────────────────────────────────────────────────────────

  /// @dev emitted when the lpActivator enables LP-only staking mode
  event LpModeActivated(address indexed lpToken);

  // ─── Shared reward injection ────────────────────────────────────────────────

  /// @dev emitted when the rewarder deposits USDT into the active pool
  event RewardNotified(address indexed notifier, uint256 amount);

  /// @dev emitted when queued rewards (deposited while no stakers existed) are flushed
  event QueuedRewardFlushed(uint256 amount);

  // ─── LP staking ────────────────────────────────────────────────────────────

  /// @dev emitted when a user provides ARC+USDT liquidity and opens an LP stake
  event LpStaked(
    address indexed user,
    uint256 indexed lpStakeId,
    uint256 lpAmount,
    uint256 arcContributed,
    uint256 usdtContributed
  );

  /// @dev emitted when an LP stake is cancelled and underlying tokens are returned
  event LpUnstaked(
    address indexed user,
    uint256 indexed lpStakeId,
    uint256 arcReturned,
    uint256 usdtReturned
  );

  /// @dev emitted when USDT reward is paid to an LP staker (on claim or cancel)
  event LpRewardClaimed(
    address indexed user,
    uint256 indexed lpStakeId,
    uint256 reward
  );
}

